    public function forCountry(array $country, string $language = 'en'): array
    {
        $code = strtoupper((string)($country['code'] ?? ''));
        $key = $code !== '' ? $code : 'GLOBAL';
        $profiles = $this->profiles();
        $profile = $profiles[$key] ?? $profiles['GLOBAL'];
        $profile['country_name'] = (string)($country['name'] ?? '');
        $profile['currency_code'] = (string)($country['currency_code'] ?? 'USD');
        $profile['currency_symbol'] = (string)($country['currency_symbol'] ?? '$');
        $profile['language'] = $language;
        $profile['security_points'] = $this->securityPoints($profile['variant']);
        $profile['process'] = $this->process($profile['variant']);
        $profile['resources'] = $this->resources($profile['variant']);
        $profile['faq'] = $this->faq($profile, $country);
        return $profile;
    }

