    private function profile(string $variant,string $kicker,string $hero,string $sub,string $introTitle,string $introBody,string $whyTitle,string $whyBody,string $philosophyTitle,string $philosophyBody,string $finalTitle,string $finalBody): array
    {
        return compact('variant','kicker','hero','sub','introTitle','introBody','whyTitle','whyBody','philosophyTitle','philosophyBody','finalTitle','finalBody') + [
            'primary_cta' => 'Explore investments',
            'secondary_cta' => 'Create account',
            'trust' => ['Clear offering terms','Protected account access','Traceable transaction records','Portfolio visibility'],
            'portfolio_title' => 'Keep the full investment journey in view',
            'portfolio_body' => 'Track investment positions, transaction history, maturity information, deposits and withdrawals from one organised account.',
            'security_title' => 'Security that supports the investment experience',
            'risk_title' => 'Clarity also means being clear about risk',
            'risk_body' => 'Investing involves risk. Projected returns are illustrative terms of an offering, not guaranteed results. Review the company information, offering terms and applicable disclosures before making a decision.',
            'resources_title' => 'Build a stronger investment process',
            'featured_title' => 'Opportunities worth a closer look',
            'featured_body' => 'Review the business and the offering terms together before deciding whether an opportunity fits your objectives.',
        ];
    }

    private function securityPoints(string $variant): array
    {
        $sets = [
            'minimal' => ['Secure sign-in and session controls','Optional two-factor authentication','Protected private documents','Clear account activity records'],
            'premium' => ['Layered account access controls','Two-factor authentication support','Protected document handling','Auditable transaction records'],
            'precision' => ['Strong credential handling','Two-factor authentication support','Structured financial records','Protected private documentation'],
            'structured' => ['Secure authentication controls','Traceable account sessions','Immutable financial ledger records','Controlled private document access'],
            'vibrant' => ['Protected account access','Two-factor authentication support','Clear transaction history','Private document protection'],
            'warm' => ['Secure account access','Two-factor authentication support','Visible transaction records','Protected personal documents'],
            'modern' => ['Modern account security controls','Two-factor authentication support','Traceable transaction activity','Protected private files'],
            'editorial' => ['Secure account access','Two-factor authentication support','Clear transaction records','Protected private documentation'],
            'institutional' => ['Secure authentication controls','Two-factor authentication support','Immutable financial ledger records','Protected private documentation'],
        ];
        return $sets[$variant] ?? $sets['institutional'];
    }

    private function process(string $variant): array
    {
        return [
            ['01','Create your account','Set up secure access and complete the information required for your account.'],
            ['02','Explore opportunities','Review companies and compare the investment terms currently available to you.'],
            ['03','Review before investing','Examine price, projected outcome, duration and supporting company information before confirming.'],
            ['04','Track the position','Follow transactions, investment positions and maturity information from your account.'],
        ];
    }

    private function resources(string $variant): array
    {
        return [
            ['How to read an opportunity','Separate company facts from offering terms and understand what each tells you.'],
            ['Understanding projected returns','Treat projections as terms to evaluate, not promises of future performance.'],
            ['Think about time horizon','Consider how the investment duration fits your own liquidity needs and objectives.'],
        ];
    }

    private function faq(array $profile, array $country): array
    {
        $currency = (string)($country['currency_code'] ?? 'USD');
        return [
            ['What information can I review before investing?','Each active opportunity can include company information, investment price, projected return structure, duration, availability and supporting source information.'],
            ['Are projected returns guaranteed?','No. Projected returns describe the configured terms of an offering and are not a guarantee of investment performance.'],
            ['Which currency will I see?',"Investment amounts for your account experience are presented in {$currency} unless an individual offering states otherwise."],
            ['Can I track an investment after purchase?','Yes. Your account keeps investment positions, transactions and maturity information organised for ongoing review.'],
            ['How is my account protected?','The platform uses secure authentication controls and supports additional safeguards such as two-factor authentication.'],
        ];
    }
